<script setup lang="ts">
import {supplementLabels,supplementValue,supplementOptions,supplementHints} from '../../domain/supplement';
import {merchantLabels} from '../../domain/merchant';
import AppIcon from '../../components/AppIcon.vue';
import {ref,computed,watch,nextTick} from 'vue';
import ActionButton from '../../components/ActionButton.vue';
import EmbeddedMap from '../../components/EmbeddedMap.vue';
import {mapPlaces} from '../../domain/map';
import {onLoad,onShow,onHide,onUnload} from '@dcloudio/uni-app';
import {listPlaces,getPlace,catalogMode,catalogError} from '../../services/catalog';
import {coreFields,evidenceKinds,evidenceFresh,costLabels,zoneLabels,practical,seatLabels,freshSeat,wifiLabel,matchesSearch,type Feedback,type SeatStatus,type Place} from '../../domain/place';
import {readSaved,toggleSaved,copyText,notify,readFeedback,writeFeedback,placeLink,openMenu,openLocation} from '../../adapters/platform';
import {request,loadSession,session,errorMessage} from '../../services/api';
const mapStatus=ref('loading'),embeddedMap=ref<InstanceType<typeof EmbeddedMap>>();
const remoteBusy=ref(false),sourceUrl=ref(''),closureCount=ref(0),missingPlace=ref(false),routeLoading=ref(false);
const cloudSeats=computed(()=>Object.fromEntries(places.value.filter(p=>!p.demo).map(p=>[p.id,p.seat])) as Record<string,Feedback['seat']>);
const places=ref<Place[]>([]),place=ref<Place>(),saved=ref<string[]>([]),cost=ref('all'),zone=ref('all'),search=ref(''),category=ref('全部类型'),mode=ref('map'),savedOnly=ref(false),pin=ref(''),wifiOpen=ref(false);
const district=ref('全部片区'),hovered=ref(''),zoom=ref(1),compared=ref<string[]>([]),detailTab=ref('essentials'),lastSaved=ref('');
const districts=['全部片区','静安','徐汇','黄浦','长宁','浦东','普陀','虹口','杨浦','闵行','宝山','嘉定','松江','青浦','奉贤','金山','崇明'];
const dialog=ref(''),step=ref(1),reason=ref(''),detail=ref(''),visitDate=ref(new Date().toLocaleDateString('sv-SE')),period=ref('下午'),spend=ref(''),note=ref('');
const verification=ref('all'),supplementField=ref('plugs'),supplementAnswer=ref<string|boolean|string[]>(''),supplementNote=ref(''),supplementSource=ref('');
watch(supplementField,()=>supplementAnswer.value='');
function toggleSupplementZone(value:string){const selected=Array.isArray(supplementAnswer.value)?supplementAnswer.value:[];supplementAnswer.value=selected.includes(value)?selected.filter(v=>v!==value):[...selected,value];}
async function submitSupplement(){if(remoteBusy.value||!place.value)return;if(supplementAnswer.value===''){notify('请填写本次到访看到的情况');return;}remoteBusy.value=true;try{await request('places/'+place.value.id+'/supplements','POST',{field:supplementField.value,value:supplementAnswer.value,date:visitDate.value,text:supplementNote.value,sourceUrl:supplementSource.value});dialog.value='';supplementNote.value='';supplementAnswer.value='';supplementSource.value='';await community();notify('已提交，审核后更新这一项；可在我的贡献查看');}catch(e){notify(errorMessage(e));}finally{remoteBusy.value=false;}}
const confirmFields=ref<string[]>([]),confirmNote=ref('');
const feedback=ref<Feedback>({visits:[],helpful:[]}),clock=ref(Date.now());
const facts=computed(()=>place.value?practical[place.value.id]:undefined);
const seat=computed(()=>freshSeat(feedback.value.seat,clock.value));
const reasons=['怀疑永久闭店','暂时停业 / 当天未开放','不再接受电脑办公','费用 / 菜单 / 设施有误','其他信息问题'];
async function community(){if(!place.value||place.value.demo)return;const r=await request('places/'+place.value.id+'/community');feedback.value={visits:r.visits,helpful:r.visits.filter((v:any)=>v.helpful).map((v:any)=>v.id),seat:r.seat||undefined};const row=places.value.find(p=>p.id===place.value!.id);if(row)row.seat=r.seat||undefined;closureCount.value=r.closureReports;}
function contribute(){uni.navigateTo({url:'/pages/contribute/index'});}
function seatTone(id:string){const p=places.value.find(p=>p.id===id);const seat=freshSeat(p?.demo?readFeedback(id).seat:cloudSeats.value[id],clock.value);return seat?'seat-'+seat.status:'tone-unknown';}
function persist(){if(place.value)writeFeedback(place.value.id,feedback.value);}
function showDialog(name:string){dialog.value=name;step.value=1;clock.value=Date.now();if(name==='report'&&feedback.value.report){reason.value=feedback.value.report.reason;visitDate.value=feedback.value.report.date;detail.value=feedback.value.report.detail;}if(name==='confirm'){confirmFields.value=[];confirmNote.value='';}}
async function updateSeat(status:SeatStatus){if(remoteBusy.value)return;remoteBusy.value=true;try{if(place.value&&!place.value.demo){await request('places/'+place.value.id+'/seats','POST',{status});await community();notify('空位反馈已保存到云端，1 小时后过期');}else{feedback.value.seat={status,at:Date.now()};persist();notify('演示反馈已保存在本机');}clock.value=Date.now();dialog.value='';}catch(e){notify(errorMessage(e));}finally{remoteBusy.value=false;}}
const parking=ref<any[]>([]),parkingState=ref('idle'),parkingError=ref('');
async function loadParking(){if(!place.value||parkingState.value==='loading')return;if(place.value.demo){parkingState.value='demo';return;}parkingState.value='loading';parkingError.value='';try{const result=await request('places/'+place.value.id+'/parking');parking.value=result.items;parkingState.value=result.state;}catch(e){parkingState.value='error';parkingError.value=errorMessage(e);}}
function jump(id:string){detailTab.value=id;if(id==='parking'&&parkingState.value==='idle')void loadParking();}
async function submitVisit(){if(remoteBusy.value)return;if(!note.value.trim()||!/^\d{4}-\d{2}-\d{2}$/.test(visitDate.value)||Number.isNaN(Date.parse(visitDate.value))||visitDate.value>new Date().toLocaleDateString('sv-SE')){notify('请填写有效到访日期与体验');return;}if(spend.value&&(!Number.isFinite(Number(spend.value))||Number(spend.value)<0)){notify('请输入有效消费金额');return;}remoteBusy.value=true;try{const v={date:visitDate.value,period:period.value,text:note.value.trim(),spend:spend.value.trim()};if(place.value&&!place.value.demo){await request('places/'+place.value.id+'/reviews','POST',v);await community();notify('体验已保存，审核后公开署名');}else{feedback.value.visits.unshift({...v,id:String(Date.now())});persist();notify('体验已保存到本机预览');}note.value='';dialog.value='';}catch(e){notify(errorMessage(e));}finally{remoteBusy.value=false;}}
async function submitReport(){if(remoteBusy.value)return;if(!detail.value.trim()||!visitDate.value){notify('请填写日期和判断依据');return;}remoteBusy.value=true;try{const v={reason:reason.value,date:visitDate.value,detail:detail.value.trim()};if(place.value&&!place.value.demo){const kind=reason.value==='怀疑永久闭店'?'closed':reason.value.startsWith('暂时')?'temporary':reason.value.startsWith('不再')?'laptop':'information';const r=await request('places/'+place.value.id+'/report','PUT',{...v,kind,sourceUrl:sourceUrl.value});dialog.value='';if(r.visibility==='hidden'){notify('已按两份独立依据标记社区闭店并隐藏');back();}else{await community();notify('纠错已保存到云端');}}else{feedback.value.report=v;persist();dialog.value='';notify('已保存本机纠错，尚未提交社区');}}catch(e){notify(errorMessage(e));}finally{remoteBusy.value=false;}}
function toggleConfirm(key:string){if(confirmFields.value.includes(key)){confirmFields.value=confirmFields.value.filter(x=>x!==key);return;}if(confirmFields.value.length>=2){notify('每次最多核对 2 项，其余项可以留到下次');return;}confirmFields.value=confirmFields.value.concat(key);}
async function submitConfirm(){if(remoteBusy.value||!place.value||place.value.demo)return;if(!confirmFields.value.length){notify('请选择你本次核对的信息项');return;}if(confirmNote.value.trim().length<2){notify('请用至少两个字描述现场情况');return;}const id=place.value.id;remoteBusy.value=true;try{const r=await request('places/'+id+'/confirm','POST',{fields:confirmFields.value,note:confirmNote.value.trim()});if(r.saved){place.value=await getPlace(id);const row=places.value.find(p=>p.id===id);if(row&&place.value){row.evidence=place.value.evidence;row.confirmations=place.value.confirmations;row.updatedAt=place.value.updatedAt;}notify('到访核对已提交，审核通过后展示');}else{notify('你今天已提交过这些项目，请在我的贡献查看进度');}dialog.value='';}catch(e){notify(errorMessage(e));}finally{remoteBusy.value=false;}}
async function useful(id:string){const active=!feedback.value.helpful.includes(id);if(place.value&&!place.value.demo){try{await request('reviews/'+id+'/helpful','PUT',{active});await community();}catch(e){notify(errorMessage(e));}}else{feedback.value.helpful=active?feedback.value.helpful.concat(id):feedback.value.helpful.filter(x=>x!==id);persist();}}
const categories=['全部类型','咖啡馆','公共空间','联合办公','自习室','图书馆','其他'];
const costs=[{key:'all',label:'全部费用'},{key:'free',label:'免费'},{key:'purchase',label:'需消费'},{key:'paid',label:'付费工位'},{key:'unknown',label:'费用待确认'}];
const zones=[{key:'all',label:'不限'},{key:'quiet',label:'安静工作'},{key:'discussion',label:'多人讨论'},{key:'booth',label:'独立通话'}];
onLoad(async options=>{if(options?.saved)savedOnly.value=true;if(options?.id){routeLoading.value=true;place.value=await getPlace(String(options.id));missingPlace.value=!place.value;if(place.value?.demo)feedback.value=readFeedback(String(options.id));else if(place.value){try{await community();}catch(e){notify(errorMessage(e));}}if(place.value&&['essentials','menu','rules','parking','sources','community'].includes(String(options.tab)))jump(String(options.tab));routeLoading.value=false;}});
let ticker:ReturnType<typeof setInterval>|undefined;
function stopClock(){if(ticker)clearInterval(ticker);}
onShow(async()=>{saved.value=readSaved().filter(id=>id.startsWith('demo-'));clock.value=Date.now();stopClock();ticker=setInterval(()=>clock.value=Date.now(),30000);await loadSession();places.value=await listPlaces();saved.value=readSaved().filter(id=>id.startsWith('demo-'));if(session.value){try{const r=await request('saved');saved.value=[...new Set(saved.value.filter(id=>id.startsWith('demo-')).concat(r.ids))];}catch(e){notify(errorMessage(e));}}if(place.value&&!place.value.demo){try{await community();}catch(e){notify(errorMessage(e));}}});
onHide(stopClock);onUnload(stopClock);
const filtered=computed(()=>places.value.filter(p=>(verification.value==='all'||(verification.value==='verified'?!p.discovery:!!p.discovery))&&(cost.value==='all'||p.cost===cost.value)&&(district.value==='全部片区'||p.district===district.value)&&(category.value==='全部类型'||p.type===category.value)&&(zone.value==='all'||p.zones.some(z=>z===zone.value))&&(!savedOnly.value||saved.value.includes(p.id))&&matchesSearch(p,search.value)));
const selectedPin=computed(()=>filtered.value.find(p=>p.id===pin.value));
function cardSeat(id:string){const p=places.value.find(p=>p.id===id);const recent=freshSeat(p?.demo?readFeedback(id).seat:cloudSeats.value[id],clock.value);return recent?seatLabels[recent.status]+' · 近期反馈':'空位待确认';}
async function retryCatalog(){places.value=await listPlaces();}
function account(){uni.navigateTo({url:'/pages/me/index'});}
function clear(){verification.value='all';district.value='全部片区';pin.value='';cost.value='all';zone.value='all';category.value='全部类型';search.value='';savedOnly.value=false;}
function open(id:string){uni.navigateTo({url:'/pages/index/index?id='+encodeURIComponent(id)});}
function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.reLaunch({url:'/pages/index/index'});}
function goSaved(){if(place.value)uni.reLaunch({url:'/pages/index/index?saved=1'});else savedOnly.value=!savedOnly.value;}
async function save(id:string){const p=place.value?.id===id?place.value:places.value.find(p=>p.id===id);if(p?.demo){const local=toggleSaved(id);saved.value=[...new Set(saved.value.filter(x=>!x.startsWith('demo-')).concat(local))];}else{try{const active=!saved.value.includes(id);await request('saved/'+id,'PUT',{saved:active});saved.value=active?saved.value.concat(id):saved.value.filter(x=>x!==id);}catch(e){notify(errorMessage(e));return;}}lastSaved.value=saved.value.includes(id)?id:'';}
function changeCategory(e:{detail:{value:string|number}}){category.value=categories[Number(e.detail.value)];}
async function copyWifi(){try{await copyText('DEMO-ONLY');notify('已复制演示密码，不是真实网络');}catch{notify('复制失败，请手动选择');}}
async function share(){if(!place.value)return;try{await copyText(placeLink(place.value.id));notify('已复制地点链接；访问权限保持不变');}catch{notify('当前无法复制');}}

const comparison=computed(()=>places.value.filter(p=>compared.value.includes(p.id)));
const filterCount=computed(()=>Number(verification.value!=='all')+Number(cost.value!=='all')+Number(zone.value!=='all')+Number(category.value!=='全部类型')+Number(district.value!=='全部片区'));
const filterSummary=computed(()=>[verification.value==='all'?'':verification.value==='verified'?'已审核办公条件':'待核实地点',cost.value==='all'?'':costLabels[cost.value as keyof typeof costLabels],zone.value==='all'?'':zoneLabels[zone.value as keyof typeof zoneLabels],category.value==='全部类型'?'':category.value,district.value==='全部片区'?'':district.value].filter(Boolean).join(' / '));
watch(filtered,rows=>{if(!rows.some(p=>p.id===pin.value))pin.value='';});
function select(id:string){pin.value=id;hovered.value='';mode.value='map';}
function compare(id:string){if(compared.value.includes(id)){compared.value=compared.value.filter(x=>x!==id);return;}if(compared.value.length>=3){notify('最多同时对比 3 个地点');return;}compared.value.push(id);}
function suggest(){const rows=filtered.value;if(!rows.length)return;const index=rows.findIndex(p=>p.id===pin.value);select(rows[(index+1)%rows.length].id);}
function changeDistrict(e:{detail:{value:string|number}}){district.value=districts[Number(e.detail.value)];}
function scale(by:number){if(mapStatus.value==='ready'){embeddedMap.value?.zoomBy(by>0?1:-1);return;}zoom.value=Math.max(1,Math.min(1.6,Math.round((zoom.value+by)*10)/10));}
function resetMap(){embeddedMap.value?.resetView();zoom.value=1;pin.value='';hovered.value='';}
// #ifdef H5
let previousFocus:HTMLElement|null=null;
watch([dialog,wifiOpen],async([d,w])=>{if(d||w){previousFocus=document.activeElement as HTMLElement;await nextTick();(document.querySelector('.backdrop [tabindex="0"]') as HTMLElement)?.focus();}else{previousFocus?.focus();}});
function overlayKeys(e:KeyboardEvent){if(!dialog.value&&!wifiOpen.value)return;if(e.key==='Escape'){dialog.value='';wifiOpen.value=false;return;}if(e.key!=='Tab')return;const nodes=Array.from(document.querySelectorAll('.backdrop [tabindex="0"],.backdrop input,.backdrop textarea')).filter(el=>(el as HTMLElement).offsetParent!==null) as HTMLElement[];const first=nodes[0],last=nodes[nodes.length-1];if(!first)return;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
window.addEventListener('keydown',overlayKeys);onUnload(()=>window.removeEventListener('keydown',overlayKeys));
// #endif
</script>
<template>
<view class="shell" :class="{'explore-shell':!place,'detail-shell':!!place}">
 <view class="product-body" :aria-hidden="(dialog||wifiOpen)?true:undefined">
 <view class="topbar">
  <ActionButton class="brand" aria-label="流动工位首页" @click="place?back():clear()"><image class="brand-mark" src="/static/brand/logo-icon.png" mode="aspectFit"/><view class="brand-words"><text>流动工位</text><text class="brand-sub">FlowSeat</text></view></ActionButton>
  <view class="primary-nav"><ActionButton :class="{current:!savedOnly&&!place}" @click="place?back():(savedOnly=false)">探索工位</ActionButton><ActionButton :class="{current:savedOnly}" @click="goSaved">我的收藏 <text v-if="saved.length" class="count">{{saved.length}}</text></ActionButton></view>
  <view class="nav"><ActionButton class="contribute-nav" @click="contribute">推荐地点 ＋</ActionButton><text class="city">上海</text><ActionButton class="icon-button profile" aria-label="我的账号" @click="account"><AppIcon name="user-round"/></ActionButton></view>
 </view>
 <view v-if="missingPlace" class="error-box">地点不存在或已隐藏。<ActionButton class="underlink" @click="back">返回探索</ActionButton></view><view v-if="routeLoading" class="notice">正在读取地点…</view><template v-if="!place&&!routeLoading&&!missingPlace">
 <view class="explore-heading"><view><view class="small-tag editorial-eyebrow">SHANGHAI · WORK FROM ANYWHERE</view><view class="workspace-title">找个座位，进入心流。<view class="heading-period"><AppIcon name="arrow-up-right"/></view></view><view class="heading-caption">Find your seat. Find your flow.</view></view><view class="discovery-tools"><view class="search"><text class="search-symbol"><AppIcon name="search"/></text><input v-model="search" aria-label="搜索地点、地址或片区" placeholder="搜索地点、地址或片区…"/><ActionButton v-if="search" class="icon-button" aria-label="清除搜索" @click="search=''"><AppIcon name="x"/></ActionButton></view><ActionButton class="filter-trigger" :class="{selected:filterCount}" @click="showDialog('filters')"><text class="filter-icon"><AppIcon name="sliders-horizontal"/></text> 筛选 <text v-if="filterCount" class="count">{{filterCount}}</text></ActionButton></view></view>
 <view class="intent-bar"><view class="intent-options"><ActionButton v-for="(z,i) in zones" :key="z.key" class="intent" :class="{active:zone===z.key}" :aria-pressed="zone===z.key" @click="zone=z.key"><AppIcon :name="['map','user-round','users','phone'][i]"/>{{['随处开工','独自专注','一起讨论','电话会议'][i]}}</ActionButton></view><view class="type-options"><ActionButton v-for="c in categories" :key="c" :class="{active:category===c}" @click="category=c">{{c==='全部类型'?'全部':c}}</ActionButton></view></view>
 <view v-if="catalogMode==='community'" class="catalog-banner"><text class="status-chip tone-unknown">真实地点 · 持续核实</text><text>地点来自腾讯位置服务。标为「待核实」的地点，尚未确认电脑办公条件。</text></view><view v-if="catalogMode==='demo'" class="catalog-banner"><text class="status-chip tone-unknown">示例模式</text><text>社区地图还没有正式收录，以下为虚构地点。</text><ActionButton class="underlink" @click="contribute">推荐第一处</ActionButton></view><view v-if="catalogMode==='error'" class="error-box">{{catalogError}}<ActionButton class="underlink" @click="retryCatalog">重新加载</ActionButton></view><view v-if="catalogMode==='loading'" class="notice">正在读取社区地点…</view>
 <view class="workspace">
  <view class="places-panel" :class="{'mobile-hide':mode==='map'}"><view class="list-heading"><view><text class="results-title">{{savedOnly?'收藏的地点':'探索上海地点'}}</text><text class="result-count">{{filtered.length}} 处</text></view><picker :range="districts" @change="changeDistrict"><view class="district-picker">{{district}} ⌄</view></picker></view>
   <view v-if="filterCount" class="active-filters"><text>{{filterSummary}}</text><ActionButton class="text-button" @click="clear">清除</ActionButton></view>
   <view v-if="!filtered.length" class="empty"><view class="empty-symbol"><AppIcon name="search"/></view><view>这次没有匹配的工位</view><text>试试放宽费用、片区或工作区域。</text><ActionButton class="black-button" @click="clear">清除筛选</ActionButton></view>
   <view class="place-list"><view v-for="(p,index) in filtered" :key="p.id" class="place-card" :style="{animationDelay:Math.min(index,5)*35+'ms'}" :class="{selected:pin===p.id,'is-hovered':hovered===p.id}" @mouseenter="hovered=p.id" @mouseleave="hovered=''"><ActionButton class="card-select" :aria-label="'在地图上查看 '+p.name" :aria-pressed="pin===p.id" @click="select(p.id)"><view class="card-art"><image :src="'/static/room-'+p.drawing+'.svg'" mode="aspectFit"/><text class="art-type">{{p.type}}</text></view><view class="card-copy"><view class="meta">{{p.district}} <text class="status-chip" :class="'tone-'+p.cost">{{costLabels[p.cost]}}</text></view><view class="card-name">{{p.name}}</view><view v-if="p.discovery" class="candidate-label">办公条件待核实</view><view class="card-budget">{{practical[p.id].budget}}<text>{{p.cost==='purchase'?' / 预估消费':''}}</text></view><view class="card-facts"><text>{{p.plugs==='待确认'?'插座待确认':p.plugs+'插座'}}</text><text>{{p.chair}}</text></view><view class="card-seat" :class="seatTone(p.id)">{{cardSeat(p.id)}}</view></view></ActionButton><ActionButton class="save-button" :class="{saved:saved.includes(p.id),pop:lastSaved===p.id}" :aria-label="(saved.includes(p.id)?'取消收藏 ':'收藏 ')+p.name" :aria-pressed="saved.includes(p.id)" @click="save(p.id)"><AppIcon name="heart"/></ActionButton><view class="card-actions"><ActionButton class="compare-check" :class="{checked:compared.includes(p.id)}" :aria-pressed="compared.includes(p.id)" @click="compare(p.id)"><text><AppIcon :name="compared.includes(p.id)?'square-check':'square'"/></text> 对比</ActionButton><ActionButton class="text-button" @click="open(p.id)">查看详情 <AppIcon name="arrow-up-right"/></ActionButton></view></view></view>
   <view class="list-footnote"><text class="demo-dot"/> {{catalogMode==='community'?'社区贡献 · 请结合来源与最近反馈判断':'虚构地点 · 仅用于体验产品'}}<view>Laptop-friendly places for freelancers,<text class="line-break"> </text>remote workers &amp; solo founders.</view></view>
  </view>
