<view class="footer"><text>流动工位 / FlowSeat</text><text>Find your seat. Find your flow.</text></view></view>  <view v-if="dialog" class="backdrop" @click="dialog=''"><view class="modal flow-modal" :class="{wide:dialog==='compare'}" role="dialog" aria-modal="true" aria-label="地点操作" @click.stop><view class="row"><text class="kicker">{{dialog==='filters'?'筛选条件':dialog==='compare'?'地点对比':dialog==='menu'?(place?.demo?'演示菜单':'商家菜单'):dialog==='report'?'地点纠错':dialog==='seat'?'空位反馈':dialog==='confirm'?'到访核对':dialog==='supplement'?'补充一项':'体验记录'}}</text><ActionButton class="icon-button close" aria-label="关闭弹窗" @click="dialog=''"><AppIcon name="x"/></ActionButton></view>
<template v-if="dialog==='supplement'"><view class="section-title">让下一位，少一点不确定。</view><view class="description">只补充亲自到访确认的信息。提交后先审核，再更新地点。</view><view class="field-label">这次补充哪一项</view><view class="option-grid"><ActionButton v-for="(label,key) in supplementLabels" :key="key" class="option" :class="{active:supplementField===key}" @click="supplementField=String(key)">{{label}}</ActionButton></view><view class="field-label">现场情况</view><view v-if="supplementField==='zones'" class="option-grid"><ActionButton v-for="o in supplementOptions.zones" :key="String(o.value)" class="option" :class="{active:Array.isArray(supplementAnswer)&&supplementAnswer.includes(String(o.value))}" :aria-pressed="Array.isArray(supplementAnswer)&&supplementAnswer.includes(String(o.value))" @click="toggleSupplementZone(String(o.value))">{{o.label}}</ActionButton><ActionButton class="option" :class="{active:Array.isArray(supplementAnswer)&&!supplementAnswer.length}" @click="supplementAnswer=[]">未设专门分区</ActionButton></view><view v-else-if="supplementOptions[supplementField]" class="option-grid"><ActionButton v-for="o in supplementOptions[supplementField]" :key="String(o.value)" class="option" :class="{active:supplementAnswer===o.value}" @click="supplementAnswer=o.value">{{o.label}}</ActionButton></view><input v-else v-model="supplementAnswer" class="form-input" aria-label="现场情况" :placeholder="supplementHints[supplementField]||'描述本次到访确认的情况'" :maxlength="supplementField==='menuUrl'?1000:supplementField==='budget'?70:['stay','entry'].includes(supplementField)?160:100"/><view class="field-label">到访日期</view><picker mode="date" :value="visitDate" :end="new Date().toLocaleDateString('sv-SE')" @change="visitDate=$event.detail.value"><view class="form-input">{{visitDate}}</view></picker><view class="field-label">说说依据</view><textarea v-model="supplementNote" class="form-textarea short" aria-label="补充依据" placeholder="例如：靠窗一排看到 4 个插座，其他座位没有确认" maxlength="240"/><input v-model="supplementSource" class="form-input" aria-label="补充来源链接" placeholder="公开来源 HTTPS 链接（可选）"/><view class="notice">不要求填完整张表。没有公开依据的办公许可、桌面或开放时间，仍需进一步核实。</view><ActionButton v-if="session?.displayName" class="black-button" :disabled="remoteBusy" @click="submitSupplement">{{remoteBusy?'正在提交…':'提交补充审核'}}</ActionButton><ActionButton v-else class="black-button" @click="account">{{session?'先设置贡献署名':'登录后补充'}}</ActionButton></template>
<template v-if="dialog==='filters'"><view class="section-title">找到适合你的工位</view><view class="field-label">核实状态</view><view class="option-grid"><ActionButton v-for="o in [{key:'all',label:'全部地点'},{key:'verified',label:'已审核办公条件'},{key:'candidate',label:'待核实地点'}]" :key="o.key" class="option" :class="{active:verification===o.key}" :aria-pressed="verification===o.key" @click="verification=o.key">{{o.label}}</ActionButton></view><view class="meta">地图有记录不等于允许办公。已审核条件也可能变化，请查看核对日期。</view><view class="field-label">使用费用</view><view class="option-grid"><ActionButton v-for="o in costs" :key="o.key" class="option" :class="{active:cost===o.key}" @click="cost=o.key">{{o.label}}</ActionButton></view><view class="field-label">工作区域</view><view class="option-grid"><ActionButton v-for="z in zones" :key="z.key" class="option" :class="{active:zone===z.key}" @click="zone=z.key">{{z.label}}</ActionButton></view><view class="field-label">地点类型</view><view class="option-grid"><ActionButton v-for="c in categories" :key="c" class="option" :class="{active:category===c}" @click="category=c">{{c}}</ActionButton></view><view class="field-label">上海片区</view><view class="option-grid"><ActionButton v-for="d in districts" :key="d" class="option" :class="{active:district===d}" @click="district=d">{{d}}</ActionButton></view><view class="sheet-actions"><ActionButton class="text-button" @click="clear">重置条件</ActionButton><ActionButton class="black-button" @click="dialog=''">显示 {{filtered.length}} 个地点</ActionButton></view></template>
<template v-if="dialog==='compare'"><view class="section-title">哪一处，更适合你？</view><view class="description">对比办公条件；未知信息不作推断，费用以场地方为准。</view><scroll-view scroll-x class="compare-scroll"><view class="comparison-table" :style="{minWidth:comparison.length>2?'600px':'360px'}"><view class="compare-row"><view class="compare-label">地点</view><view v-for="p in comparison" :key="p.id" class="compare-value"><image :src="'/static/room-'+p.drawing+'.svg'" mode="aspectFit"/><ActionButton class="text-button" @click="dialog='';open(p.id)">{{p.name}} <AppIcon name="arrow-up-right"/></ActionButton></view></view><view v-for="field in ['预算','类型','插座','座椅','Wi-Fi','工作区域']" :key="field" class="compare-row"><view class="compare-label">{{field}}</view><view v-for="p in comparison" :key="p.id" class="compare-value">{{field==='预算'?practical[p.id].budget:field==='类型'?p.type:field==='插座'?p.plugs:field==='座椅'?p.chair:field==='Wi-Fi'?wifiLabel(p.wifi):(p.zones.length?p.zones.map(z=>zoneLabels[z]).join(' / '):p.observations?.zones?'未设专门分区':'待确认')}}</view></view></view></scroll-view><view class="notice">示例地点不代表真实商家；社区地点请结合来源与到访反馈判断。</view></template>
<template v-if="dialog==='menu'"><view class="section-title">{{place?.type==='咖啡馆'?'菜单与消费':'价目与权益'}}</view><view class="description">{{place?.name}}</view><ActionButton v-if="facts?.menuUrl" class="outline-button" @click="openMenu(facts.menuUrl)">打开商家公开菜单 <AppIcon name="arrow-up-right"/></ActionButton><view v-if="facts?.menuUpdatedAt" class="meta">更新于 {{facts.menuUpdatedAt}}</view><view class="info-row" v-for="item in facts?.menu" :key="item.name"><text>{{item.name}}</text><text>{{item.price}}</text></view><view class="notice">{{place?.demo?'虚构演示菜单，非商家报价。':'菜单来自商家公开链接，可能随时调整，以现场为准。'}}</view><ActionButton class="black-button" @click="dialog=''">了解了</ActionButton></template>
<template v-if="dialog==='seat'"><view class="section-title">现在还有空位吗？</view><view class="description">只反馈你眼前的情况。1 小时后自动回到待确认。</view><ActionButton v-for="(label,key) in seatLabels" :key="key" class="choice" :disabled="remoteBusy" @click="updateSeat(key)"><text>{{label}}</text><text><AppIcon name="arrow-up-right"/></text></ActionButton><view class="notice">{{place?.demo?'示例反馈仅保存到本机。':'反馈保存到云端。'}} 临时坐满不会触发闭店或隐藏地点。</view></template>
<template v-if="dialog==='visit'"><view class="section-title">记录一次办公体验。</view><view class="field-label">到访日期</view><input v-model="visitDate" class="form-input" placeholder="YYYY-MM-DD"/><view class="chips period"><ActionButton v-for="p in ['上午','下午','晚间']" :key="p" class="chip" :class="{active:period===p}" @click="period=p">{{p}}</ActionButton></view><view class="field-label">实际消费（元，选填）</view><input v-model="spend" type="digit" class="form-input" placeholder="例如 35"/><view class="field-label">你的体验</view><textarea v-model="note" class="form-textarea" maxlength="600" placeholder="插座好找吗？椅子舒服吗？这个时段安静吗？"/><ActionButton class="black-button" :disabled="remoteBusy" @click="submitVisit">{{remoteBusy?'正在保存…':place?.demo?'保存本机体验':'提交体验审核'}}</ActionButton><view class="meta">{{place?.demo?'此示例记录仅自己可见。':'公开后展示你的贡献署名，不展示登录邮箱。'}}</view></template>
<template v-if="dialog==='confirm'"><view class="section-title">我刚到访，核对信息。</view><view class="description">请确认下方当前信息与你现场看到的一致。反馈先审核，原始来源保留；信息不一致请用「地点纠错」。</view><view class="field-label">这次可以确认</view><view class="option-grid"><ActionButton v-for="f in coreFields" :key="f.key" class="option" :class="{active:confirmFields.includes(f.key)}" :aria-pressed="confirmFields.includes(f.key)" @click="toggleConfirm(f.key)"><AppIcon :name="confirmFields.includes(f.key)?'square-check':'square'"/>{{f.label}} · {{f.key==='cost'?costLabels[place!.cost]:f.key==='hours'?place!.hours:place![f.key]?'已确认':'待确认'}}</ActionButton></view><view class="field-label">现场情况（2–200 字）</view><textarea v-model="confirmNote" class="form-textarea short" maxlength="200" placeholder="例如：18:10 仍在营业，吧台可充电，消费 ¥32"/><ActionButton class="black-button" :disabled="remoteBusy" @click="submitConfirm">{{remoteBusy?'正在保存…':'提交核对审核'}}</ActionButton><view class="notice">每次最多 2 项，每人每项每天提交一次。审核通过后单独展示到访日期与说明，不覆盖原始依据，也不修改字段值。</view></template>
<template v-if="dialog==='report'"><view class="section-title">{{step===1?'哪一处信息有问题？':'补充你的判断依据。'}}</view><template v-if="step===1"><ActionButton v-for="r in reasons" :key="r" class="choice" :class="{selected:reason===r}" @click="reason=r"><text>{{r}}</text><text>{{reason===r?'●':'○'}}</text></ActionButton><ActionButton class="black-button" @click="reason?step=2:notify('请先选择问题类型')">下一步</ActionButton></template><template v-else><view class="meta" @click="step=1">← {{reason}}</view><view class="field-label">发现日期</view><input v-model="visitDate" class="form-input" placeholder="YYYY-MM-DD"/><view class="field-label">现场情况或可核对的公开来源</view><textarea v-model="detail" class="form-textarea" maxlength="600" placeholder="例如：门上张贴停业告示；请勿填写个人联系方式"/><view class="notice">一次独立反馈标记怀疑闭店；两位独立用户提供依据并核对来源后，才标记社区闭店、默认隐藏。暂时停业与坐满单独处理。</view><template v-if="!place?.demo"><view class="field-label">公开依据链接{{reason==='怀疑永久闭店'?'（必填）':'（选填）'}}</view><input v-model="sourceUrl" class="form-input" placeholder="https://…"/></template><ActionButton class="black-button" :disabled="remoteBusy" @click="submitReport">{{remoteBusy?'正在保存…':place?.demo?'保存本机纠错':'提交地点纠错'}}</ActionButton></template><view class="meta">{{place?.demo?'演示纠错不会影响真实地点。':'同一用户与同源依据会去重；两份独立近期来源才标记社区闭店，支持审核恢复。'}}</view></template>
</view></view>
  <view v-if="wifiOpen" class="backdrop" @click="wifiOpen=false"><view class="modal" @click.stop><view class="row"><text class="kicker">GET CONNECTED</text><ActionButton class="icon-button close" aria-label="关闭 Wi-Fi 信息" @click="wifiOpen=false"><AppIcon name="x"/></ActionButton></view><view class="section-title">先连上，再开始。</view><view class="notice">仅演示连接信息，不是真实 Wi-Fi。</view><view class="info-row"><text>网络名称</text><text>FlowSeat-Demo</text></view><view class="info-row"><text>密码</text><text>DEMO-ONLY</text></view><ActionButton class="black-button" @click="copyWifi">复制密码</ActionButton><view class="meta">Web 无法直接切换设备 Wi-Fi。真实连接信息仅在场地方允许公开时提供。</view></view></view>
</view>
</template>
